edits.newText:
final spectrum = settings.settingsNotifier.value;
final isLinuxCassette = Platform.isLinux && cfg is CassetteScreenConfig;
final showDebugLayoutToggle =
    kDebugMode || (!kIsWeb && Platform.isMacOS);

final rows = <Object>[

edits.oldText:
// DISPLAY — per-screen knobs.
_Group('DISPLAY'),
if (kDebugMode || (!kIsWeb && Platform.isMacOS))
  _Toggle('void-settings-debug-layout', 'debug layout',
      settings.debugLayoutNotifier.value, settings.toggleDebugLayout),
...displayRows(cfg),

edits.newText:
// DISPLAY — per-screen knobs.
// On Linux, Cassette's variant/text/haptics controls live immediately
// under the screen selector, so we skip duplicating them here.
if (!isLinuxCassette || showDebugLayoutToggle) ...[
  _Group('DISPLAY'),
  if (showDebugLayoutToggle)
    _Toggle('void-settings-debug-layout', 'debug layout',
        settings.debugLayoutNotifier.value, settings.toggleDebugLayout),
  if (!isLinuxCassette) ...displayRows(cfg),
],
